-- Tabelle Tinn ridotte alle colonne lette dall estrazione, con i tipi del DB
-- del Comune (dialect 1: DATE e TIMESTAMP, DOUBLE PRECISION per gli importi).
-- Solo struttura per il selftest: nessun dato reale.
CREATE TABLE GFANCON1 (CODICE INTEGER, PARTITA_IVA CHAR(20), COD_FISCALE CHAR(20));
CREATE TABLE GFBIPRN1 (TIPO CHAR(1), ESERCIZIO SMALLINT, ANNO SMALLINT, CAPITOLO INTEGER, ARTICOLO SMALLINT,
  DESCRIZIONE CHAR(150), PREV_COMP_RES DOUBLE PRECISION);
CREATE TABLE GFVASTN1 (TIPO CHAR(1), ESERCIZIO SMALLINT, ANNO SMALLINT, CAPITOLO INTEGER, ARTICOLO SMALLINT,
  IMPORTO DOUBLE PRECISION);
CREATE TABLE GFIMDEN1 (SIGLA SMALLINT, ESERCIZIO SMALLINT, ANNO SMALLINT, ANNO_CREA SMALLINT, NUMERAZIONE INTEGER,
  PROGRESSIVO SMALLINT, CAPITOLO INTEGER, ARTICOLO SMALLINT, CREDITORE INTEGER, IMPORTO DOUBLE PRECISION,
  V_VAR_P DOUBLE PRECISION, V_VAR_N DOUBLE PRECISION, CODICE_CIG VARCHAR(30), ANNULLATO CHAR(1), DESCRIZIONE CHAR(250));
CREATE TABLE GFPNCGN1 (ESERCIZIO SMALLINT, NUMERO INTEGER, FE_ID_SDI_S VARCHAR(250), NUMERO_DOCUMENTO VARCHAR(50),
  DOC_DATA TIMESTAMP, TOTALE_DOCUMENTO DOUBLE PRECISION, CODICE_CIG VARCHAR(30), ANAGRAFICA INTEGER);
CREATE TABLE GFLIQUN1 (ESERCIZIO SMALLINT, ANNO_CREA SMALLINT, SIGLA SMALLINT, NUMERAZIONE INTEGER, PROGRESSIVO SMALLINT,
  IM_ANNO_CREA SMALLINT, IM_NUMERAZIONE INTEGER, IM_PROGRESSIVO SMALLINT, IM_ESERCIZIO SMALLINT, IM_SIGLA SMALLINT,
  FA_ESERCIZIO SMALLINT, FA_NUMERO INTEGER, CODICE_CIG VARCHAR(30), IMPORTO DOUBLE PRECISION, ANNULLATO CHAR(1));
CREATE TABLE GFRIPNC (ID INTEGER, IMPORTO DOUBLE PRECISION, FA_ESERCIZIO SMALLINT, FA_NUMERO INTEGER,
  NC_ESERCIZIO SMALLINT, NC_NUMERO INTEGER);
CREATE TABLE GFMATEN1 (ESERCIZIO SMALLINT, PROGRESSIVO INTEGER, D_EMISSIONE TIMESTAMP, STATO_MAND CHAR(1));
CREATE TABLE GFMARIN1 (ESERCIZIO SMALLINT, PROGRESSIVO INTEGER, RIGA SMALLINT, LI_ANNO_CREA SMALLINT, LI_SIGLA SMALLINT,
  LI_NUMERAZIONE INTEGER, LI_PROGRESSIVO SMALLINT, DATA_PAG TIMESTAMP, IMP_PAGATO DOUBLE PRECISION);
COMMIT;
